  "issues": [
    {
      "iid": 12,
      "title": "Add recent locations dropdown to search",
      "description": "After a user searches for a city, save it to a recent searches list (up to 5 entries,\nstored in localStorage). Show a dropdown with recent cities when the search field is focused.\n\n**Acceptance Criteria**\nGiven a user who has previously searched for cities\nWhen they focus the search input\nThen a dropdown of up to 5 recent cities is displayed\nAnd clicking a city loads its weather immediately",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:51.303Z"
    },
    {
      "iid": 11,
      "title": "Auto-detect user location on first load",
      "description": "On first load, request the browser's geolocation API to detect the user's city and\npre-populate the search field. If the user denies the permission, fall back to a default city.",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:50.985Z"
    },
    {
      "iid": 10,
      "title": "Clean up the UI",
      "description": "The dashboard UI looks a bit cluttered. Make it look nicer and more professional.\nSome things could be aligned better and the colours don't look right.",
      "labels": [
        "Open",
        "Task"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:50.656Z"
    },
    {
      "iid": 9,
      "title": "Add temperature unit toggle (Celsius / Fahrenheit)",
      "description": "Add a toggle in the dashboard header that switches all displayed temperatures between\nCelsius and Fahrenheit. The selected unit should persist in localStorage.\n\n**Acceptance Criteria**\nGiven a user viewing the dashboard\nWhen they click the C°/F° toggle\nThen all temperature values update immediately and the unit is saved to localStorage",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:50.333Z"
    },
    {
      "iid": 8,
      "title": "Persist user theme preference across page reloads",
      "description": "The app should remember the user's theme choice (light/dark) between visits.\nOn load, read the stored preference from localStorage and apply it before the first render\nto avoid a flash of unstyled content.",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:50.032Z"
    },
    {
      "iid": 7,
      "title": "Add dark mode toggle to navigation bar",
      "description": "Add a button to the top navigation bar that toggles between light and dark themes.\nThe preference should be saved to localStorage so it persists across sessions.\n\n**Acceptance Criteria**\nGiven a user on any page\nWhen they click the dark mode toggle in the nav bar\nThen the theme switches immediately and the preference is saved to localStorage",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:49.696Z"
    },
    {
      "iid": 6,
      "title": "Improve the search feature",
      "description": "The search doesn't work well. Make it better and faster so users can find cities more easily.",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:49.139Z"
    },
    {
      "iid": 5,
      "title": "Deploy weather-app to staging environment",
      "description": "Set up a CI pipeline that builds the weather-app Docker image and deploys it to the\nstaging environment on every push to main.",
      "labels": [
        "In Progress",
        "Task"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:48.801Z"
    },
    {
      "iid": 4,
      "title": "Handle auth token expiry in API calls",
      "description": "All API calls should transparently retry after refreshing the auth token.\n\n**Acceptance Criteria**\nGiven a valid session that has just expired\nWhen the user performs an action that triggers an API call\nThen the app silently refreshes the token and completes the request without prompting the user\n\nNote: this depends on the token refresh mechanism being available.",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:48.511Z"
    },
    {
      "iid": 3,
      "title": "Implement JWT token refresh",
      "description": "The app must refresh expired JWT tokens without logging the user out.\n\nThe /auth/refresh endpoint should be called automatically when a 401 response is received.\nNo user interaction should be required for a seamless token refresh.",
      "labels": [
        "Open",
        "Story"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:48.222Z"
    },
    {
      "iid": 2,
      "title": "Fix the thing on the settings page",
      "description": "The notification preference resets to its default after the settings page reloads.\nThe thing that saves it is broken. Fix it.",
      "labels": [
        "Bug",
        "Open"
      ],
      "state": "opened",
      "assignee": null,
      "updatedAt": "2026-08-29T20:12:47.849Z"
    },
    {
      "iid": 1,
      "title": "Add 5-day weather forecast widget",
      "description": "Users should be able to see a multi-day forecast on the dashboard.\n\nThe widget should show temperature highs and lows for each day and update automatically.",
